package com.youngone.mediacontrol.identity.domain;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="hr_identity_conflicts")public class HrIdentityConflict{@Id private UUID id;@Column(name="source_id",nullable=false)private UUID sourceId;@Column(name="sync_run_id")private UUID syncRunId;@Column(name="external_object_id",length=300)private String externalObjectId;@Column(name="immutable_person_key",length=200)private String immutablePersonKey;@Column(name="conflict_type",nullable=false,length=50)private String conflictType;@Lob@Column(name="details_json",nullable=false,columnDefinition="LONGTEXT")private String detailsJson;@Column(nullable=false,length=20)private String status;@Column(name="detected_at",nullable=false)private Instant detectedAt;protected HrIdentityConflict(){}public HrIdentityConflict(UUID sourceId,String externalId,String immutableKey,String type,Instant now){id=UUID.randomUUID();this.sourceId=sourceId;externalObjectId=externalId;immutablePersonKey=immutableKey;conflictType=type;detailsJson="{}";status="OPEN";detectedAt=now;}}